#include <stdio.h>
int main(void)
{
    int a[3][3]={{0,1,0},{1,0,1},{0,1,0}}, d[3]={0,-1,-1};
    int q[3]={0}, head=0, tail=1;
    while (head<tail) {
        int u=q[head++];
        for(int v=0;v<3;v++) {
            if(a[u][v] && d[v]==-1) { d[v]=d[u]+1; q[tail++]=v; }
        }
    }
    printf("%d\n",d[2]);
    return 0;
}
